import fs from "node:fs";

const database = fs.readFileSync(new URL("./database.types.ts", import.meta.url), "utf8");
const schema = fs.readFileSync(new URL("./schema.gen.ts", import.meta.url), "utf8");
if (!database.includes("Generated by `supabase gen types`")) process.exit(1);
if (!schema.includes('SchemaVersion = "consumer-fixture-v1"')) process.exit(1);
